def deny_network(*args, **kwargs):
    # Never include destination/configuration values in diagnostics.
    raise RuntimeError("V00 network disabled; use an offline fixture")


class NoApplicationStartup(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname == "app.main" or fullname == "app.seed" or fullname.startswith("app.scripts"):
            raise RuntimeError("V00 application startup disabled")
        return None


class ExactCollection:
    def __init__(self, requested):
        self.requested = requested

    def pytest_collection_modifyitems(self, session, config, items):
        import pytest

        actual = [item.nodeid for item in items]
        if len(actual) != len(self.requested) or set(actual) != set(self.requested):
            raise pytest.UsageError("V00 collection differs from exact authorized nodeids")


def main(argv=None) -> int:
    requested = list(sys.argv[1:] if argv is None else argv)
    # Validate before pytest, settings, collection, or any app import.
    if (not requested or len(set(requested)) != len(requested)
            or any(node not in ALLOWED_NODEIDS for node in requested)):
        print("V00 rejected: supply only distinct, explicitly allowed exact nodeids", file=sys.stderr)
        return 2
    if any(name == "app" or name.startswith("app.") for name in sys.modules):
        print("V00 rejected: requires a fresh process before any app import", file=sys.stderr)
        return 2

    environment = {
        name: value for name, value in os.environ.items()
        if not name.upper().startswith(("QMDH_", "PYTEST_"))
    }
    with ExitStack() as stack:
        temporary = Path(stack.enter_context(tempfile.TemporaryDirectory(prefix="qmdh-v00-")))
        media = temporary / "media"
        media.mkdir()
        config = temporary / "pytest.ini"
        config.write_text("[pytest]\n", encoding="utf-8")
        environment.update({
            "QMDH_DATABASE_URL": "sqlite://",
            "QMDH_MEDIA_ROOT": str(media),
            "QMDH_STORAGE_BACKEND": "local",
            "QMDH_MEILISEARCH_ENABLED": "false",
            "QMDH_TASK_EXECUTION_MODE": "background",
            "QMDH_IMAGE_PROVIDER_PROFILES_JSON": "[]",
            "QMDH_AUTH_USERS_JSON": "[]",
            "QMDH_AGENT_CLIENTS_JSON": "[]",
            "QMDH_BOOTSTRAP_ADMIN_NAME": "",
            "QMDH_CHAT_TELEMETRY_ALERTS_ENABLED": "false",
            "PYTEST_DISABLE_PLUGIN_AUTOLOAD": "1",
            "PYTHONDONTWRITEBYTECODE": "1",
        })
        stack.enter_context(patch.dict(os.environ, environment, clear=True))
        old_cwd = Path.cwd()
        os.chdir(temporary)
        stack.callback(os.chdir, old_cwd)
        stack.enter_context(patch.object(sys, "path", [str(BACKEND), *sys.path]))
        stack.enter_context(patch.object(sys, "dont_write_bytecode", True))
        blocker = NoApplicationStartup()
        sys.meta_path.insert(0, blocker)
        stack.callback(sys.meta_path.remove, blocker)
        for attribute in ("create_connection", "getaddrinfo"):
            stack.enter_context(patch.object(socket, attribute, deny_network))
        for attribute in ("connect", "connect_ex", "sendto"):
            stack.enter_context(patch.object(socket.socket, attribute, deny_network))

        # __call__ alone is too late: dotenv can be read in source construction.
        from pydantic_settings.sources import DotEnvSettingsSource

        stack.enter_context(patch.object(DotEnvSettingsSource, "_read_env_files", return_value={}))
        stack.enter_context(patch.object(DotEnvSettingsSource, "__call__", return_value={}))
        import pytest

        targets = []
        for node in requested:
            filename, suffix = node.split("::", 1)
            targets.append(str(BACKEND / filename) + "::" + suffix)
        return int(pytest.main([
            "-c", str(config), "--rootdir", str(BACKEND), "--noconftest",
            "--import-mode=importlib", "-p", "no:cacheprovider", "-q", "--tb=short",
            *targets,
        ], plugins=[ExactCollection(requested)]))


if __name__ == "__main__":
    raise SystemExit(main())
